class TabBar(PagePart):
    SITE_MANAGEMENT = "site-navigation"
    SNAPSHOT = "snapshot-navigation"
    PARAMETERS = "cmeditor-navigation"
    MONITORING = '//span[text()="Monitoring and Tests"]'
    MONITORING_MEASUREMENTS = "measurements-panel-navigation"
    MONITORING_PERFORMANCE_MONITORING = "pm-panel-navigation"
    MONITORING_IP_CONNECTIVITY_TEST = "ping-panel-navigation"
    MONITORING_SYNCHRONIZATION = "sync-panel-navigation"
    CERTIFICATES = "certificates-navigation"
    MONITORING_PMTU_DISCOVERY = "pmtuDiscovery-navigation"
    RND = "rnd-navigation"

    def __init__(self, driver):
        super(TabBar, self).__init__(driver)

    def click_tab(self, id):
        """
        Click tab with given id

        :param id: tab id
        """
        self._wait_for_element_by((By.ID, id))
        li = self._driver.find_element_by_id(id)
        a = li.find_element_by_tag_name("a")
        a.click()

    def click_site_management(self):
        """
        Click site management tab.

        :return: SiteManagementPage object
        """
        self.click_tab(self.SITE_MANAGEMENT)
        return SiteManagementPage(self._driver)

    def click_snapshot(self):
        """
        Click snapshot tab.

        :return: SnapshotPage object
        """
        self.click_tab(self.SNAPSHOT)
        return SnapshotPage(self._driver)

    def click_parameters(self):
        """
        Click parameters tab.

        :return: None (Page not implemented yet)
        """
        self.click_tab(self.PARAMETERS)
        return ParametersPage(self._driver)

    def click_monitoring(self, dropdown_tab=None):
        """
        Click monitorng tab.

        :return: MonitoringPage object
        """
        self.wait_for_visibility((By.XPATH, self.MONITORING))
        self._driver.find_element_by_xpath(self.MONITORING).click()
        if not dropdown_tab:
            dropdown_tab = self.MONITORING_SYNCHRONIZATION
        synchronization_xpath = "//li[@id='{}']//a".format(dropdown_tab)
        synchronization_locator = (By.XPATH, synchronization_xpath)
        self.wait_for_visibility(synchronization_locator)
        self._driver.find_element_by_xpath(synchronization_xpath).click()
        return MonitoringPage(self._driver)

    def click_certificates(self):
        """
        Click certificates tab.

        :return: CertificatesPage object
        """
        return CertificatesPage(self._driver)

    def click_rnd(self):
        """
        Click R&D tab.

        :return: None (Page not implemented yet)
        """
        self.wait_for_visibility((By.ID, self.RND))
        self.click_tab(self.RND)
        return RndPage(self._driver)

    def click_reset_or_cancel_on_confirm_modal(self, confirm_modal, button_status):
        if button_status == 'reset' or button_status == 'activate':
            confirm_modal.confirm()
        elif button_status == 'cancel':
            confirm_modal.cancel()
        else:
            raise AttributeError('only "reset", "activate" or "cancel" can be chosen for button status')

    def expand_header(self, header_name):
        """
        Expands header with given label name
        :param header_name: header name
        """
        xpath1 = "//div[contains(@class, 'panel-heading')]//*[contains(text(), '{}')]".format(header_name)
        xpath2 = "//div[contains(@class, 'panel-heading')]//*[contains(text(), '{}')]/../" \
                 "span[contains(@class,'icon')]".format(header_name)
        self._wait_for_element_by((By.XPATH, xpath1))
        self.wait_for_visibility((By.XPATH, xpath1))
        try:
            collapsed = self._driver.find_element_by_xpath(xpath2)
            if 'right' in collapsed.get_attribute('class'):
                collapsed.click()
                time.sleep(3)
        except NoSuchElementException:
            pass

    def scroll_list_table(self, elem_xpath):
        """ Scroll list table to make sure element visiable
        :param elem_xpath: xpath of element
        """
        self._wait_for_element_by((By.XPATH, elem_xpath))
        elem = self._driver.find_element_by_xpath(elem_xpath)
        if not elem.is_displayed():
            self._driver.execute_script("arguments[0].scrollIntoView();", elem)
            self.wait_for_visibility((By.XPATH, elem_xpath))
        return elem

    def input_text(self, element, value):
        element.send_keys(Keys.CONTROL + 'a')
        element.send_keys(Keys.BACKSPACE)
        element.send_keys(value)

    def input_text_by_xpath(self, element_xpath, value):
        element = self._driver.find_element_by_xpath(element_xpath)
        self.input_text(element, value)


class LoginPage(BasicPage):
    def __init__(self, driver):
        super(LoginPage, self).__init__(driver)

    def insert_login(self, login):
        """
        Inserts given login to login field

        :param login: user login
        """
        self.insert_text_to_field("applicationLoginUsername", login)

    def insert_password(self, password):
        """
        Inserts given password to password field

        :param password: user password
        """
        self.insert_text_to_field("applicationLoginPassword", password)

    def click_login_button(self):
        """
        Clicks login button
        """
        elem = self._driver.find_element_by_id("applicationLoginButton")
        elem.click()

    def login(self, username, password, after_reset=False):
        """
        Perform user login with given credentials. If site returns warning about
        incompatible browser click proceed link.

        :param username:
        :param password:
        :param after_reset: allow login to fail. New vesions of software performs login automatically.
        :return: SiteManagementPage object
        """
        try:
            self.click_continue_if_needed()
            self.insert_login(username)
            self.insert_password(password)
            self.click_login_button()
            self.wait_for_visibility((By.ID, "user-name"), 20)
        except NoSuchElementException:
            if not after_reset:
                raise
        except TimeoutException:
            raise FailedLoginException("Login failed")
        return SiteManagementPage(self._driver)

    def click_continue_if_needed(self, timeout=10):
        """
        Proceed to next page if incompatible browser warning appeared

        :param timeout: search timeout
        """
        try:
            id = "continue"
            self._wait_for_element_by((By.ID, id), timeout)
            elem = self._driver.find_element_by_id(id)
            elem.click()
        except TimeoutException:
            pass


