    def _return_outcome_if_file_is_wrong(self):
        """
        Get reasons for commissioning failure
        :return: defaultdict
        """
        feedback_info = self._driver.execute_script("var c = document.getElementById('feedback-body')."
                                                    "getElementsByTagName('td'); var arr = []; "
                                                    "for(var index in c){arr.push(c[index].textContent)}; return arr")
        feedback_info = [item for item in feedback_info if item]
        info = list()
        for num in range(0, len(feedback_info), 2):
            info.append((feedback_info[num], feedback_info[num + 1]))
        feedback_error = dict()
        for k, v in info:
            feedback_error.setdefault(k, []).append(v)
        return feedback_error

    def wait_until_commissioning_status(self, timeout):
        """
        Wait until commissioning status returned
        :param msg: str, a string represents current status after commissioning
        :param timeout: int - max timeout func will wait for status to appear
        :return: str or defaultdict, current status or failed reasons
        """
        id = "feedback-body"
        try:
            self.wait_for_visibility((By.ID, id), timeout)
            feedback = self._return_outcome_if_file_is_wrong()
            return feedback
        except TimeoutException:
            return "Configuration successfully updated"

