    def click_on_lock_unlock_modal(self, confirm_modal, operation):
        """ Click for lock or unlock cells. """
        if operation == 'Lock' or operation == 'Unlock':
            confirm_modal.confirm(operation)
        elif operation == 'Cancel':
            confirm_modal.cancel()
        else:
            raise AttributeError("Operation is not valid: {}".format(operation))

    def _wait_for_clickable_and_return_modal(self, element_locator):
        """ Return CellsLockUnlockModal object. """
        self.wait_for_enable(element_locator)
        self._wait_for_element_by(element_locator)
        _, elem_xpath = element_locator
        self._driver.find_element_by_xpath(elem_xpath).click()

        modal_class_name = 'modal-dialog'
        self._wait_for_element_by((By.CLASS_NAME, modal_class_name))
        self.wait_for_visibility((By.CLASS_NAME, modal_class_name))
        return CellsLockUnlockModal(self._driver)

    def lock_cells(self, operation, cell_group_idx):
        """ Lock cells in cell group. """
        locator = (By.XPATH, self._LOCK_CELLS_XPATH.format(cell_group_idx))
        self.click_on_lock_unlock_modal(self._wait_for_clickable_and_return_modal(locator), operation)

    def unlock_cells(self, operation, cell_group_idx):
        """ Unlock cells in cell group. """
        locator = (By.XPATH, self._UNLOCK_CELLS_XPATH.format(cell_group_idx))
        self.click_on_lock_unlock_modal(self._wait_for_clickable_and_return_modal(locator), operation)

    def _get_led_color(self, xpath):
        """ Return the color of LED """
        try:
            self._wait_for_element_by((By.XPATH, xpath))
            hw_status = self._driver.find_element_by_xpath(xpath).get_attribute('class')
        except NoSuchElementException:
            raise NoSuchHwElement('This hw status element does not exist')
        ledcolor_pattern = re.compile(r'hw-status ledColor-(.*)')
        hw_status_ledcolor = ledcolor_pattern.match(hw_status).group(1)
        return hw_status_ledcolor

    def ru_led_status(self, frm_id=1):
        """ Return the color of RU LED """
        xpath_hw_status = "//*[@id='frm-{}']//div[contains(@class,'hw-status ledColor-')]".format(frm_id)
        return self._get_led_color(xpath_hw_status)

    def abil_led_status(self, fbb_id=1):
        """ Return the color of ABIL LED """
        xpath_hw_status = "//*[@id='fbb-{}']//div[contains(@class,'hw-status ledColor-')]".format(fbb_id)
        return self._get_led_color(xpath_hw_status)

    def asik_led_status(self, fsm_id=1):
        """ Return the color of ASIK LED """
        xpath_hw_status = "//*[@id='fsm-{}']//div[contains(@class,'hw-status ledColor-')]".format(fsm_id)
        return self._get_led_color(xpath_hw_status)

    def _wait_for_clickable_and_return_restart_modal(self, element_locator):
        modal_id = 'confirmation-modal-confirm'
        self.wait_for_visibility(element_locator)
        locator_type, elem_xpath = element_locator
        if locator_type == 'id':
            self.click_button(elem_xpath)
        elif locator_type == 'xpath':
            self._driver.find_element_by_xpath(elem_xpath).click()
        self._wait_for_element_by((By.ID, modal_id))
        return RestartModal(self._driver)

    def choose_reset_mode(self, force_reset):
        xpath = "//label[@for='force-reset-false']"
        if not force_reset:
            xpath = "//label[@for='force-reset-true']"
