    def _get_hw_status(self, hw_xpath, hw_key_xpath, hw_value_xpath):
        self._wait_for_element_by((By.XPATH, hw_xpath))
        click_event_js = 'window.get_info = function(){window.info = $(".tooltipster-base").html()};' \
                         '$(document).on("click", get_info)'
        self._driver.execute_script(click_event_js)
        time.sleep(2)
        self._driver.find_element_by_xpath(hw_xpath).click()
        html = self._driver.execute_script("return window.info")
        time.sleep(1)
        elem = etree.HTML(html)
        key_list = ['_'.join(item.lower().strip(':').split(' ')) for item in elem.xpath(hw_key_xpath)]
        value_list = elem.xpath(hw_value_xpath)
        self._driver.execute_script('$(document).unbind("click", get_info)')
        value_list = self._adjust_hw_value_list(key_list, value_list)
        return dict(zip(key_list, value_list))

    def _adjust_hw_value_list(self, hw_key_list, hw_value_list):
        if 'frequency_bands' in hw_key_list and len(hw_key_list) < len(hw_value_list):
            index = hw_key_list.index('frequency_bands')
            hw_value_list[index] = [hw_value_list[index], hw_value_list[index + 1]]
            hw_value_list.pop(index + 1)
        return hw_value_list

    def _raise_exception_if_hw_status_name_is_wrong(self, hw_status_name, hw_status):
        if hw_status_name and hw_status_name not in hw_status:
            raise AttributeError('{} can not be found in "{}"'.format(hw_status_name, hw_status))

    def _get_hw_status_by_name(self, hw_status_name, hw_status):
        self._raise_exception_if_hw_status_name_is_wrong(hw_status_name, hw_status)
        return hw_status[hw_status_name] if hw_status_name else hw_status

    def get_cell_status(self, cell_status_name, cell_index=1):
        cell_xpath = "//div[@id='cell-{}']".format(cell_index)
        hw_status = self._get_hw_status(cell_xpath, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(cell_name='cell-{}'.format(cell_index))
        return self._get_hw_status_by_name(cell_status_name, hw_status)

    def get_gps_status(self, gnss_status_name):
        gnss_hw_xpath = "//div[@id='gnss-hw-container-1']"
        gps_name_xpath = "//span[@id='gnss-hw-name-1']"
        hw_status = self._get_hw_status(gnss_hw_xpath, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(gps_name=self._driver.find_element_by_xpath(gps_name_xpath).text)
        return self._get_hw_status_by_name(gnss_status_name, hw_status)

    def get_frm_status(self, frm_status_name):
        frm_status = "//div[@id='frm-1']/div[1]"
        frm_name_xpath = "//div[contains(@class, 'hw-radio')]//div[@class='hw-id']"
        hw_status = self._get_hw_status(frm_status, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(frm_name=self._driver.find_element_by_xpath(frm_name_xpath).text)
        return self._get_hw_status_by_name(frm_status_name, hw_status)

    def get_fbb_status(self, fbb_status_name, fbb_index=1):
        fbb_xpath = "//div[@id='fbb-{}']".format(fbb_index)
        abil_name_xpath = "//div[contains(@class, 'fbb-slot-{}')]//div[@class='hw-id']".format(fbb_index)
        hw_status = self._get_hw_status(fbb_xpath, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(abil_name=self._driver.find_element_by_xpath(abil_name_xpath).text)
        return self._get_hw_status_by_name(fbb_status_name, hw_status)

    def get_fsm_status(self, fsm_status_name, fsm_index=0):
        fsm_xpath = "//div[@id='fsm-1']"
        asik_name_xpath = "//div[@class='fsm-slot-{}']//div[@class='hw-id']".format(fsm_index)
        hw_status = self._get_hw_status(fsm_xpath, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(asik_name=self._driver.find_element_by_xpath(asik_name_xpath).text)
        return self._get_hw_status_by_name(fsm_status_name, hw_status)

    def get_asod_status(self, asod_status_name, asod_index=1):
        asod_xpath = "//div[@id='fsm-{}']".format(asod_index)
        asod_name_xpath = "{}//div[@class='hw-id']".format(asod_xpath)
        hw_status = self._get_hw_status(asod_xpath, self.HW_STATUS_KEY_XPATH, self.HW_STATUS_VALUE_XPATH)
        hw_status.update(asod_name=self._driver.find_element_by_xpath(asod_name_xpath).text)
        return self._get_hw_status_by_name(asod_status_name, hw_status)

    def _check_if_alarm_history_selected(self):
        checkbox_xpath = "//input[@class='history-checkbox']"
        self._wait_for_element_by((By.XPATH, checkbox_xpath))
        elem = self._driver.find_element_by_xpath(checkbox_xpath)
        return elem.is_selected()

    def _control_alarm_history(self, show_history, timeout):
        """ Click or Unclick show alarm history checkbox """
        if show_history != self._check_if_alarm_history_selected():
            self.expand_alarm_history()
            time.sleep(timeout)

    def _control_alarm_extra_info(self, index):
        """ Click alarm row to expand or unexpand alarm extra info
        :param index: index of element
        """
        elem_xpath = "//div[@id='alarms']//tr[@class='alarm'][{}]/td[1]".format(index)
        elem = self.scroll_list_table(elem_xpath)
        elem.click()

    def _fill_alarm_filter(self, alarm_filter):
        """ fill alarm_filter into input field"""
        filter_xpath = "//div[@id='rcp-alarms-panel']//input[@type='text']"
        self._wait_for_element_by((By.XPATH, filter_xpath))
        elem = self._driver.find_element_by_xpath(filter_xpath)
        elem.clear()
        elem.send_keys(alarm_filter)

    def _get_alarm_info_list(self, alarm_xpath):
        """ Common method to get alarm info in alarm table """
        alarm_list = []
        self._wait_for_element_by((By.XPATH, alarm_xpath))
        for index, elem in enumerate(self._driver.find_elements_by_xpath(alarm_xpath)):
            self.scroll_list_table("(" + alarm_xpath + ")[{}]".format(index + 1))
            alarm_list.append(elem.text.strip())
        return alarm_list

    def _get_alarm_extra_info(self, alarm_index, key_list, value_list):
        extra_info_xpath = "//div[@id='alarms']//table[@class='extra-fault-info']//tr/td"
        self._control_alarm_extra_info(alarm_index)
        extra_info_list = self._get_alarm_info_list(extra_info_xpath)
        self._wait_for_element_by((By.XPATH, extra_info_xpath))
        for index, elem in enumerate(extra_info_list):
            if (index % 2 == 0):
                key_list.append(elem.strip().split(':')[0])
            else:
                value_list.append(elem.strip())
        self._control_alarm_extra_info(alarm_index)

    def _get_alarms_detail_info(self):
        """ Get both alarm basic and extra info and return a list of dict """
        alarm_list = []
        alarms_xpath = "//div[@id='alarms']//tr[@class='alarm']"
        alarm_column_name_xpath = "//table[@id='header-table']//th[text()]"
        key_list = self._get_alarm_info_list(alarm_column_name_xpath)
        alarm_number = len(self._driver.find_elements_by_xpath(alarms_xpath))
        for index in range(1, alarm_number + 1):
            alarm_basic_info_xpath = "//div[@id='alarms']//tr[@class='alarm'][{}] \
                                      //*[text()]".format(index)
            value_list = self._get_alarm_info_list(alarm_basic_info_xpath)
            self._get_alarm_extra_info(index, key_list, value_list)
            alarm_list.append(dict(zip(key_list, value_list)))
        return alarm_list

    def _scroll_to_active_alarms(self):
        active_alarms_xpath = "//div[contains(@class, 'panel-heading')]//*[contains(text(), 'Active Alarms')]"
        self._wait_for_element_by((By.XPATH, active_alarms_xpath))
        elem = self._driver.find_element_by_xpath(active_alarms_xpath)
        self._driver.execute_script("arguments[0].scrollIntoView();", elem)
        self.wait_for_visibility((By.XPATH, active_alarms_xpath))

    def get_alarms_info(self, alarm_filter=None, show_history=False, timeout=3):
        """
        Get alarm detail information on site management page
        :param alarm_filter: str, filled into the input as alarm filter, can be None if no filter needed
        :param show_history: boolean true/false, whether need to return alarm history info
        :param timeout: int, default is 3(secs), wait time after click history checkbox
        :return: list of dict, or empty list if no alarms, no errors returned
        """
        self._scroll_to_active_alarms()
        alarm_table_id = "table-body"
        if alarm_filter:
            self._fill_alarm_filter(alarm_filter)
        self._control_alarm_history(show_history, int(timeout))
        self._wait_for_element_by((By.ID, alarm_table_id))
        alarm_list = self._get_alarms_detail_info()
        return alarm_list

    def get_current_software_version_info(self):
        """
        Get current software version
        """
        version_xpath_dict = {
             'active': '//td[@id="active-sw-version"]',
             'passive': '//td[@id="passive-sw-version"]',
             'planned': '//td[@id="planned-sw-version"]'
         }
        self.wait_for_visibility((By.XPATH, version_xpath_dict.get('active')))
        version_values = [self._driver.find_element_by_xpath(xpath).text.strip()
                          for xpath in version_xpath_dict.values()]
        return dict(zip(version_xpath_dict.keys(), version_values))

    def click_rollback_button(self, timeout):
        """
        Click rollback button
        """
        rollback_btn_id = "site-rollback-button"
        self.wait_for_enable((By.ID, rollback_btn_id))
        self.click_button(rollback_btn_id)
        time.sleep(timeout)
        try:
            dialog_rollback_btn_id = "modal-Rollback-button-confirm"
            self._wait_for_element_by((By.ID, dialog_rollback_btn_id), timeout)
            self.click_button(dialog_rollback_btn_id)
        except TimeoutException:
            logging.info("There's no response after clicking rollback button")

    def get_click_rollback_error_msg(self, timeout):
        """
        Click rollback button
        """
        rollback_btn_id = "site-rollback-button"
        error_xpath = "//*[@id='softwareupdate']/div[2]/div[2]/table/tbody/tr[3]/td[3]/div/span"
        dialog_rollback_close_btn_id = "modal-Close-button-confirm"
        self.wait_for_enable((By.ID, rollback_btn_id))
        self.click_button(rollback_btn_id)
        time.sleep(timeout)
        self._wait_for_element_by((By.ID, dialog_rollback_close_btn_id), timeout)
        self.click_button(dialog_rollback_close_btn_id)
        self._wait_for_element_by((By.XPATH, error_xpath))
        return self._driver.find_element_by_xpath(error_xpath).text

    def get_click_rollback_button_status(self, timeout):
        """
        Click rollback button and get button status
        """
        rollback_btn_id = "site-rollback-button"
        try:
            self.wait_for_enable((By.ID, rollback_btn_id), timeout)
            return "enable"
        except TimeoutException:
            return "disable"

    def check_current_status(self):
        """
                Click check current status button and get related information
        """
        pre_check_xpath = "//*[@id='pre-check']"
        pre_check_id = "pre-check"
        version_xpath_dict = {
             'CPU': '//*[@id="softwareupdate"]//td[contains(text(), "CPU")]/..',
             'Memory': '//*[@id="softwareupdate"]//td[contains(text(), "Memory")]/..',
             'Active file system': '//*[@id="softwareupdate"]//td[contains(text(), "Active file system")]/..',
             'Passive file system': '//*[@id="softwareupdate"]//td[contains(text(), "Passive file system")]/..',
             'PDL': '//*[@id="softwareupdate"]//span[contains(text(), "PDL")]'
         }
        self.wait_for_enable((By.XPATH, pre_check_xpath))
        self.click_button(pre_check_id)
        self._wait_for_element_by((By.XPATH, version_xpath_dict.get('CPU')))
        self.wait_for_visibility((By.XPATH, version_xpath_dict.get('CPU')))
        version_values = [self._driver.find_element_by_xpath(xpath).text.strip()
                          for xpath in version_xpath_dict.values()]
        return dict(zip(version_xpath_dict.keys(), version_values))

    def get_bts_profile(self):
        bts_profile = self._driver.find_element_by_xpath("//span[@id='current-profile']")
        return bts_profile.text

    def click_save_sw_update_report(self):
        """ Click Save SW Update Report button """
        save_sw_update_report = 'save-sw-update-report'
        self.wait_for_enable((By.ID, save_sw_update_report))
        self.click_button(save_sw_update_report)

    def get_ru_software_version(self, timeout=60):
        version_xpath = {'Module': '//td[@class="frmUnitName"]',
                         'Active': '//td[@class="frmUnitSwVersion"]',
                         'SW_info': '//td[@class="frmSwInfo"]'}
        self._wait_for_element_by((By.CLASS_NAME, "frmUnitSwVersion"), timeout)
        return dict([(name, self._driver.find_element_by_xpath(xpath).text.strip())
                     for name, xpath in version_xpath.items()])

    def check_airscale_software_versions(self):
        """
        Get airscale software versions
        """
        base_xpath = '//tr[@id="rap-sw-row-1-1"]/td[{}]'
        airscale_version_xpaths = {
            'RAP': base_xpath.format(1),
            'Module': base_xpath.format(2),
            'Active': base_xpath.format(3),
            'Passive': base_xpath.format(4),
            'SW info': base_xpath.format(5)
        }
        self.wait_for_visibility((By.XPATH, airscale_version_xpaths.get('Active')))
        self.wait_for_visibility((By.XPATH, airscale_version_xpaths.get('Passive')))
        return dict([(name, self._driver.find_element_by_xpath(xpath).text.strip())
                     for name, xpath in airscale_version_xpaths.items()])

    def select_rap_from_rap_summary(self, cell_index):
        try:
            self._driver.execute_script(
                "document.querySelector('#rapSummary > div table > "
                "tbody > tr:nth-child({})').click()".format(cell_index))
        except JavascriptException:
            logging.warning("can not select rap in table")

    def get_bts_id(self):
        bts_id_xpath = '//*[@id="cbts-id"]'
        return self._driver.find_element_by_xpath(bts_id_xpath).text.strip()

    def get_software_version(self):
        bts_software_version_xpath = '//*[@id="cbts-sw-version"]'
        return self._driver.find_element_by_xpath(bts_software_version_xpath).text.strip()

    def _select_asod_rap(self, rap_xpath, asod_xpath):
        self._wait_for_element_by((By.XPATH, rap_xpath))
        for elem in self._driver.find_elements_by_xpath(rap_xpath):
            elem.click()
            if not self.check_if_exists((By.XPATH, asod_xpath)):
                continue
            break

    def _scroll_view_for_asod(self, xpath):
        self._wait_for_element_by((By.XPATH, xpath))
        elem = self._driver.find_element_by_xpath(xpath)
        self._driver.execute_script("arguments[0].scrollIntoView();", elem)
        self.wait_for_visibility((By.XPATH, xpath))
        elem.click()

    def get_optical_if_info_for_ru(self, index=1):
        opt_if_xpath = "//*[@id='frm-1']//*[@id='frm-1-sfpport-{}']".format(index)
        opt_if_key_xpath = "//*[@id='componentName']/following-sibling::span"
        opt_if_value_xpath = "//*[@id='connectedTo']"
