    def is_counters_tree_not_empty(self, timeout=15):
        """
        Checks whether tree with downloaded counters has any items in it.
        :param timeout: time to wait for counters tree items to be visible
        :type timeout: int
        :return: True if counters tree is not empty, False otherwise.
        :rtype: bool
        :raises: UnexpectedCountersTreeState
        """
        self.wait_for_visibility((By.ID, "object-list"), 10)

        if self.check_if_visible((By.XPATH, '//*[@id="object-list"]/li[1]'), timeout):
            return True
        elif self.check_if_visible((By.ID, "pm-no-counters")):
            return False
        else:
            raise UnexpectedElementState("Unexpected state of counters tree")

    def get_counters_total(self, timeout=10):
        """
        Gets total number of downloaded counters in counters tree.
        :param timeout: time to wait for counters total to be available
        :type timeout: int
        :return: total number of counters in tree.
        :rtype: int
        """
        text_element_id = "number-of-counters"
        self.wait_for_visibility((By.ID, text_element_id), timeout)
        text_element = self._driver.find_element_by_id(text_element_id)

        return int(text_element.text.split(" ")[1])

    def _filter_counter(self, counter_xpath, filter_object=None):
        try:
            self.wait_for_visibility((By.XPATH, counter_xpath), 10)
        except:
            raise UnexpectedElementState('please check whether "filter_param" is existed')
        if filter_object:
            object_xpath = "//li[@data-object-id='{}']".format(filter_object)
            try:
                self._driver.find_element_by_xpath(''.join([object_xpath, counter_xpath])).click()
            except:
                raise UnexpectedElementState('please check whether "filter_object" is existed')
        else:
            self._driver.find_element_by_xpath(counter_xpath).click()

    def _click_element_until_attribute_value_exist(self, xpath, attribute, value, timeout):
        end_time = time.time() + timeout
        while time.time() < end_time:
            try:
                elems = self._driver.find_elements_by_xpath(xpath)
                for elem in elems:
                    if elem.is_displayed():
                        self._driver.execute_script("arguments[0].scrollIntoView();", elem)
                        elem.click()

                traget_elements_xpath = (xpath + '/..//*[contains(@{}, "{}")]').format(attribute, value)
                if len(elems) == len(self._driver.find_elements_by_xpath(traget_elements_xpath)):
                    break
            except NoSuchElementException:
                continue
        else:
            raise NoSuchHwElement

    def _compatible_filter_counter(self, counter_xpath, filter_object, timeout=60):
        object_xpath = '//li[@data-id="{}"]'.format(filter_object)
        object_child_xpath = '//li[contains(@data-id, "{}")]'.format(filter_object + '_')
        self._click_element_until_attribute_value_exist(object_xpath, 'class', 'list-shown', timeout)
        self._click_element_until_attribute_value_exist(object_child_xpath, 'class', 'list-shown', timeout)
        self._driver.find_element_by_xpath(counter_xpath).click()

    def filter_counter(self, filter_param, filter_object=None):
        """
        Filter specific counter by param
        :param filter_param: str, param to locate specific counter
        :param filter_object: str, default None, param to locate specific object of counter. If sw version is above
        5G19A_621051184, filter_object has to be passed.
        :return: OrderedDict
        """
        cbts_sw_release_name_id = 'cbts-sw-release-name'
        cbts_sw_version_id = 'cbts-sw-version'
        cbts_sw_release_name = self._driver.find_element_by_id(cbts_sw_release_name_id).text
        cbts_sw_version = self._driver.find_element_by_id(cbts_sw_version_id).text

        filter_input_xpath = "//input[@id='pm-search-counter']"
        counter_xpath = "//div[contains(text(),'{}')]".format(filter_param)
        pm_result_xpath = "//div[@id='pm-result']//tbody//tr"
        self.wait_for_visibility((By.XPATH, filter_input_xpath))
        elem = self._driver.find_element_by_xpath(filter_input_xpath)
        self.input_text(elem, filter_param)

        if cbts_sw_release_name > '5G19A' or cbts_sw_version.replace('.', '') > '5G19A_621051184':
            self._compatible_filter_counter(counter_xpath, filter_object)
        else:
            self._filter_counter(counter_xpath, filter_object)

        self.wait_for_visibility((By.XPATH, pm_result_xpath))
        result = OrderedDict()
        for elem in self._driver.find_elements_by_xpath(pm_result_xpath):
            td_elem = elem.find_elements_by_xpath('./td')
            result.update({td_elem[0].text: td_elem[1].text})
        return result

