    VLAN_XPATH = "//label[contains({},'VLAN')]/../..//input".format(_DES_OR_SELF_TEXT)
    DSCP_XPATH = "//label[contains({},'DSCP')]/../..//input".format(_DES_OR_SELF_TEXT)


    ROUTE_SUBNET_XPATH = "//label[contains({},'Route')]/../..//input[contains(@placeholder, 'Subnet')]".format(_DES_OR_SELF_TEXT)
    ROUTE_MASK_XPATH = "//label[contains({},'Route')]/../..//input[contains(@placeholder, 'Mask')]".format(_DES_OR_SELF_TEXT)
    ROUTE_GW_XPATH = "//label[contains({},'Route')]/../..//input[contains(@placeholder, 'Gateway')]".format(_DES_OR_SELF_TEXT)


    CP_DEST_IP_XPATH = "//label[contains({},'CPlane')]/../..//input[contains(@placeholder, 'IP')]".format(_DES_OR_SELF_TEXT)
    CP_DEST_PORT_XPATH = "//label[contains({},'CPlane')]/../..//input[contains(@placeholder, 'Port')]".format(_DES_OR_SELF_TEXT)
    UP_DEST_IP_XPATH = "//label[contains({},'UPlane')]/../..//input[contains(@placeholder, 'IP')]".format(_DES_OR_SELF_TEXT)
    UP_DEST_PORT_XPATH = "//label[contains({},'UPlane')]/../..//input[contains(@placeholder, 'Port')]".format(_DES_OR_SELF_TEXT)
    APPLY_CHANGES_BUTTON_XPATH = "//button[contains(string(), 'Apply changes')]"

    def __init__(self, driver):
        super(RndPage, self).__init__(driver)

    def switch_test_state_to_gnb_without_ru(self):
        locator = (By.XPATH, self.AIRPHONEGNBWORU_XPATH)
        self.wait_for_visibility(locator)
        radio_elem = self._driver.find_element_by_xpath(self.AIRPHONEGNBWORU_XPATH)
        if radio_elem.is_selected():
            return None
        radio_elem.click()

        self._driver.find_element_by_id(self.ENTER_TEST_STATE_BUTTON_XPATH).click()
        return RndResetModal(self._driver)

    def switch_test_state_to_gnb_with_ru(self):
        locator = (By.ID, self.EXIT_TEST_STATE_BUTTON_XPATH)
        self.wait_for_visibility(locator, 5)
        try:
            self.wait_for_enable(locator, 5)
        except:
            raise ElementIsDisable("exit button is not clickable")
        self._driver.find_element_by_id(self.EXIT_TEST_STATE_BUTTON_XPATH).click()
        return RndExitModal(self._driver)

    def _switch_to_panel_by_xpath(self, panel_xpath):
        self.wait_for_visibility((By.XPATH, panel_xpath))
        self.click_element_by_xpath(panel_xpath)

    def activate_cplane_traces(self, collector_ip, collector_port):
        """
        activate cplane traces on R&D --> Trace and Snapshot Management panel
        :param: collector_ip: str, data collector ip
        :param: collector_port: str, data collector port
        """
        self._switch_to_panel_by_xpath(self.CPLANE_XPATH)
        self.input_text_by_xpath(self.CPLANE_COLLECTOR_IP_XPATH, collector_ip)
        self.input_text_by_xpath(self.CPLANE_COLLECTOR_PORT_XPATH, collector_port)
        self.click_element_by_xpath(self.ACTIVATE_CP_TRACES_BUTTON_XPATH)

    def stop_cplane_traces(self):
        """
        stop cplane traces on R&D --> Trace and Snapshot Management panel
        """
        self._switch_to_panel_by_xpath(self.CPLANE_XPATH)
        self.click_element_by_xpath(self.STOP_CP_TRACES_BUTTON_XPATH)

    def _insert_configuration_changes_for_cu(self, dscp, cp_dest_ip, cp_dest_port,
                                             up_dest_ip, up_dest_port, route_subnet, route_mask, route_gw):
        self.input_text_by_xpath(self.ROUTE_SUBNET_XPATH, route_subnet)
        self.input_text_by_xpath(self.ROUTE_MASK_XPATH, route_mask)
        self.input_text_by_xpath(self.ROUTE_GW_XPATH, route_gw)
        self.input_text_by_xpath(self.DSCP_XPATH, dscp)
        self.input_text_by_xpath(self.CP_DEST_IP_XPATH, cp_dest_ip)
        self.input_text_by_xpath(self.CP_DEST_PORT_XPATH, cp_dest_port)
        self.input_text_by_xpath(self.UP_DEST_IP_XPATH, up_dest_ip)
        self.input_text_by_xpath(self.UP_DEST_PORT_XPATH, up_dest_port)

    def _insert_configuration_changes_for_common_source(self, source_ip, vlan, dscp,
                                                        cp_dest_ip, cp_dest_port, up_dest_ip, up_dest_port):
        self.input_text_by_xpath(self.SOURCE_IP_XPATH, source_ip)
        self.input_text_by_xpath(self.VLAN_XPATH, vlan)
        self.input_text_by_xpath(self.DSCP_XPATH, dscp)
        self.input_text_by_xpath(self.CP_DEST_IP_XPATH, cp_dest_ip)
        self.input_text_by_xpath(self.CP_DEST_PORT_XPATH, cp_dest_port)
        self.input_text_by_xpath(self.UP_DEST_IP_XPATH, up_dest_ip)
        self.input_text_by_xpath(self.UP_DEST_PORT_XPATH, up_dest_port)

    def wait_until_apply_change_status(self, timeout=30):
        """
        Wait until apply changes result returned
        :param timeout: int - max timeout func will wait for status to appear
        :return: str or defaultdict, current status or failed reasons
        """
        try:
            msg_xpath = '//div[@class="ant-message"]//div[@class="ant-message-notice"]'
            self.wait_for_visibility((By.XPATH, msg_xpath), timeout)
            result = self._driver.find_element_by_xpath(msg_xpath).text
            return result
        except TimeoutException:
            return ""

    def apply_common_configuration_changes(self, source_ip, vlan, dscp, cp_dest_ip, cp_dest_port, up_dest_ip,
                                           up_dest_port, source_name=None, route_subnet='', route_mask='', route_gw=''):
        """
        apply changes for common configuration on R&D --> Trace and Snapshot Management panel
        :param: route_subnet: str, Route Subnet
        :param: route_mask: str, Route Mask
        :param: route_gw: str, Route Gateway
        :param: source_ip: str, Source Ip
        :param: vlan: str, VLAN
        :param: dscp: str, DSCP
        :param: cp_dest_ip: str, CPlane Destination IP
        :param: cp_dest_port: str, CPlane Destination Port
        :param: up_dest_ip: str, UPlane Destination IP
        :param: up_dest_port: str, UPlane Destination Port
        :param: source_name: str, if source_name is None, select firstone checkbox

        """
        self._switch_to_panel_by_xpath(self.COMMON_CONFIGURATION_XPATH)

        if source_name:
            checkbox_xpath = self.COMMON_CONFIGURATION_TAB_CONTENT_XPATH + \
                             "//table//td[text()='{}']/..//input[@type='checkbox']".format(source_name)
            self.select_checkbox_by_xpath(checkbox_xpath)
        else:
            self.select_checkbox_by_xpath(self.SELECT_SOURCE_CHECKBOX_XPATH)

        if source_name and 'cu' in source_name.lower():
            self._insert_configuration_changes_for_cu(dscp, cp_dest_ip, cp_dest_port, up_dest_ip, up_dest_port,
                                                      route_subnet, route_mask, route_gw)
        else:
            self._insert_configuration_changes_for_common_source(source_ip, vlan, dscp, cp_dest_ip, cp_dest_port,
                                                                 up_dest_ip, up_dest_port)

        self.click_element_by_xpath(self.APPLY_CHANGES_BUTTON_XPATH)
        return self.wait_until_apply_change_status()

    def clear_fields_in_common_configuration(self):
        """
        clear fields in common configuration on R&D --> Trace and Snapshot Management panel
        """
        self._switch_to_panel_by_xpath(self.COMMON_CONFIGURATION_XPATH)
        self.select_checkbox_by_xpath(self.COMMON_CONFIG_FIELDS_CHECKBOX)
        self.click_element_by_xpath(self.CLEAR_FIELDS_BUTTON_XPATH)

    def _select_element_by_xpath_using_wait_for_element(self, panel_xpath):
        self._wait_for_element_by((By.XPATH, panel_xpath))
        self._driver.find_element_by_xpath(panel_xpath).click()

    def _get_element_text_after_loading_finished(self, element_xpath, timeout=1):
        self._wait_for_element_by((By.XPATH, element_xpath), timeout)
        time.sleep(timeout)
        return self._driver.find_element_by_xpath(element_xpath).text

    def _select_du_by_index(self, du_index, tab_name="UPlane Component"):
        tab_content_xpath = self.UPLANE_COMPONENT_TAB_CONTENT_XPATH

        if tab_name == "UPlane Sherpa":
            tab_content_xpath = self.UPLANE_SHERPA_TAB_CONTENT_XPATH

        arrow_down_xpath = tab_content_xpath + '//*[@id="TA-combobox-withdisableditemsbutton"]'
        du_option_xpath = tab_content_xpath + '//*[@id="mySelectlist_item"]/ul//span[text()="{}"]'.format(du_index)

        self.click_element_by_xpath(arrow_down_xpath)
        self._select_element_by_xpath_using_wait_for_element(du_option_xpath)

    def _select_pci_info(self, pci_info):
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_COMPONENT_PCILIST_COMBOBOX_XPATH)
        pcilist_xpath = "//ul[@role='listbox']/li[contains(.,'{}')]".format(pci_info)
        self._select_element_by_xpath_using_wait_for_element(pcilist_xpath)
        self._driver.find_element_by_xpath("//body").click()

    def _select_l2_hi_source_type(self, src_type):
        source_xpath = "//div[contains(@style, 'display: flex;')]//label[contains(@class, 'ant-radio-wrapper')]"\
                       "//span[contains(text(), '{}')]/..//input[contains(@type,'radio')]".format(src_type)
        self._select_element_by_xpath_using_wait_for_element(source_xpath)

    def activate_uplane_component_trace(self, cp_type, pci_info, src_type, du_id):
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_COMPONENT_XPATH)

        component_type_xpath = "//div[contains(@style, 'display: flex;')]//li[contains(text(), '{}')]".format(cp_type)
        self._select_element_by_xpath_using_wait_for_element(component_type_xpath)

        if cp_type == 'L2-HI':
            self._select_l2_hi_source_type(src_type)

        if src_type == 'DU':
            self._select_du_by_index(du_id)

        if pci_info is not None:
            self._select_pci_info(pci_info)

        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_ACTIVATE_BUTTON_XPATH)
        try:
            return self._get_element_text_after_loading_finished(self.UPLANE_COMPONENT_ERROR_INFO_XPATH)
        except TimeoutException:
            return ""

    def start_uplane_component_trace(self, cp_type, src_type, timeout):
        return self._control_uplane_component_trace(cp_type, 'Start', src_type, timeout)

    def stop_uplane_component_trace(self, cp_type, src_type, timeout):
        return self._control_uplane_component_trace(cp_type, 'Stop', src_type, timeout)

    def _control_uplane_component_trace(self, cp_type, action, src_type, timeout=5):
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_COMPONENT_XPATH)

        switch_button_xpath = "//tbody[@class='css-1wbyb65 eiylbpi2']//td[contains(., '{}{}')]"\
                              "/..//span[@class='ant-switch-inner']".format(cp_type, ' ' + src_type)
        self._wait_for_element_by((By.XPATH, switch_button_xpath), timeout)
        if self._driver.find_element_by_xpath(switch_button_xpath).text != action:
            self._driver.find_element_by_xpath(switch_button_xpath).click()

        try:
            return self._get_element_text_after_loading_finished(self.UPLANE_COMPONENT_ERROR_INFO_XPATH)
        except TimeoutException:
            return ""

    def activate_uplane_sherpa(self, cp_type, src_type, du_id=0):
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_SHERPA_XPATH)

        component_type_xpath = "//div[contains(@style, 'display: flex;')]//li[contains(text(), '{}')]".format(cp_type)
        self._select_element_by_xpath_using_wait_for_element(component_type_xpath)

        if cp_type == 'L2-HI':
            source_xpath = "//div[contains(@style, 'display: flex;')]//label[contains(@class, 'ant-radio-wrapper')]"\
                           "//span[contains(text(), '{}')]/..//input[contains(@type,'radio')]".format(src_type)
            self._select_element_by_xpath_using_wait_for_element(source_xpath)

        if src_type == 'DU':
            self._select_du_by_index(du_id, tab_name="UPlane Sherpa")

        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_ACTIVATE_BUTTON_XPATH)

        try:
            return self._get_element_text_after_loading_finished(self.UPLANE_COMPONENT_ERROR_INFO_XPATH)
        except TimeoutException:
            return ""

    def start_uplane_sherpa(self, cp_type, src_type, timeout):
        return self._control_uplane_sherpa(cp_type, 'Start', src_type, timeout)

    def stop_uplane_sherpa(self, cp_type, src_type, timeout):
        return self._control_uplane_sherpa(cp_type, 'Stop', src_type, timeout)

    def _control_uplane_sherpa(self, cp_type, action, src_type, timeout=5):
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_SHERPA_XPATH)

        switch_button_xpath = "//tbody[@class='css-1ikk4sp e10q7cq22']//td[contains(., '{}{}')]"\
                              "/..//span[@class='ant-switch-inner']".format(cp_type, ' ' + src_type)
        self._wait_for_element_by((By.XPATH, switch_button_xpath), timeout)
        if self._driver.find_element_by_xpath(switch_button_xpath).text != action:
            self._driver.find_element_by_xpath(switch_button_xpath).click()

        try:
            return self._get_element_text_after_loading_finished(self.UPLANE_COMPONENT_ERROR_INFO_XPATH)
        except TimeoutException:
            return ""

    def set_uplane_filters(self, cp_type, tx, rx, src_type, du_id):
        tx_input_xpath = "//div[contains(@style, 'display: flex;')]//label[text()='TX:']/"\
                         "following-sibling::span[contains(@class,'ant-input-group-wrapper')]//input"
        rx_inout_xpath = "//div[contains(@style, 'display: flex;')]//label[text()='RX:']/"\
                         "following-sibling::span[contains(@class,'ant-input-group-wrapper')]//input"
        component_type_xpath = "//div[contains(@style, 'display: flex;')]//li[contains(text(), '{}')]".format(cp_type)
        self._select_element_by_xpath_using_wait_for_element(self.UPLANE_COMPONENT_XPATH)
        self._select_element_by_xpath_using_wait_for_element(component_type_xpath)
        if cp_type == 'L2-HI':
            self._select_l2_hi_source_type(src_type)
        if src_type == 'DU':
            self._select_du_by_index(du_id)
        self.input_text_by_xpath(tx_input_xpath, tx)
        self.input_text_by_xpath(rx_inout_xpath, rx)
        self._driver.find_element_by_xpath(self.UPLANE_SAVE_BOTTON_XPATH).click()
